{
  "name": "Barcodify Pro",
  "description": "Professional barcode label generator with single entry and bulk CSV upload support. Generates print-ready PDFs."
}

import React from 'react';
import ReactDOM from 'react-dom/client';
import App from './App';

const rootElement = document.getElementById('root');
if (!rootElement) {
  throw new Error("Could not find root element to mount to");
}

const root = ReactDOM.createRoot(rootElement);
root.render(
  <React.StrictMode>
    <App />
  </React.StrictMode>
);

export interface Product {
  id: string;
  articleName: string;
  sku: string;
  price: string;
  size: string;
  color: string;
}

export type InputMode = 'single' | 'bulk';

import jsPDF from 'jspdf';
import JsBarcode from 'jsbarcode';
import { Product } from '../types';

// Helper to generate a base64 barcode image
const generateBarcodeBase64 = (sku: string): string => {
  const canvas = document.createElement('canvas');
  JsBarcode(canvas, sku, {
    format: 'CODE128',
    displayValue: false, // We will draw the text manually in the PDF for better control
    margin: 0,
    height: 40,
    width: 2,
    fontSize: 0,
  });
  return canvas.toDataURL('image/jpeg');
};

export const generatePDF = (products: Product[]) => {
  // A4 dimensions in mm: 210 x 297
  const doc = new jsPDF({
    orientation: 'p',
    unit: 'mm',
    format: 'a4',
  });

  const pageWidth = 210;
  const pageHeight = 297;

  // Label Configuration (approx 3 x 10 grid like Avery 5160, but slightly taller for fashion tags)
  // Let's assume a standard 63.5mm x 33.9mm label or similar, fitting 3 cols.
  // For this design which is tall, we will do 3 columns, 8 rows per page.
  const cols = 3;
  const rows = 8;
  const labelWidth = 64; 
  const labelHeight = 34;
  const marginX = (pageWidth - (cols * labelWidth)) / 2;
  const marginY = 12;
  const gutterX = 2; // Spacing between cols
  const gutterY = 4; // Spacing between rows

  let colIndex = 0;
  let rowIndex = 0;

  products.forEach((product, index) => {
    // Check if new page is needed
    if (index > 0 && index % (cols * rows) === 0) {
      doc.addPage();
      colIndex = 0;
      rowIndex = 0;
    }

    const x = marginX + colIndex * (labelWidth + gutterX);
    const y = marginY + rowIndex * (labelHeight + gutterY);

    // --- Draw Label Border (Optional, helpful for cutting if not using pre-cut paper) ---
    doc.setDrawColor(200, 200, 200);
    doc.setLineWidth(0.1);
    doc.rect(x, y, labelWidth, labelHeight);

    // --- Content ---
    const centerX = x + (labelWidth / 2);

    // 1. Article Name (Top)
    doc.setFont("helvetica", "bold");
    doc.setFontSize(9);
    doc.setTextColor(0, 0, 0);

    // Truncate text if too long
    const name = product.articleName.toUpperCase();
    const splitName = doc.splitTextToSize(name, labelWidth - 4);

    // If name is too long, just take first 2 lines
    const linesToPrint = splitName.length > 2 ? splitName.slice(0, 2) : splitName;
    doc.text(linesToPrint, centerX, y + 5, { align: "center" });

    let currentY = y + 5 + (linesToPrint.length * 4); // Adjust Y based on lines

    // 2. Size & Color (Middle)
    doc.setFont("helvetica", "normal");
    doc.setFontSize(8);
    const metaText = `${product.size} • ${product.color}`;
    doc.text(metaText, centerX, currentY, { align: "center" });

    currentY += 2; // Spacer

    // 3. Barcode (Center)
    try {
      const barcodeData = generateBarcodeBase64(product.sku);
      const barcodeWidth = 40;
      const barcodeHeight = 10;
      doc.addImage(barcodeData, 'JPEG', centerX - (barcodeWidth / 2), currentY, barcodeWidth, barcodeHeight);

      currentY += barcodeHeight + 4; // Move below barcode
    } catch (e) {
      console.error("Error generating barcode for", product.sku, e);
    }

    // 4. SKU (Bottom)
    doc.setFont("courier", "bold"); // Monospace looks nice for SKU
    doc.setFontSize(10);
    doc.text(product.sku, centerX, currentY, { align: "center" });

    // 5. Price (Top Right - Small)
    if (product.price) {
        doc.setFont("helvetica", "bold");
        doc.setFontSize(7);
        // Clean price string
        const priceStr = product.price.startsWith('$') ? product.price : `$${product.price}`;
        doc.text(priceStr, x + labelWidth - 2, y + 4, { align: "right" });
    }

    // Increment Grid Position
    colIndex++;
    if (colIndex >= cols) {
      colIndex = 0;
      rowIndex++;
    }
  });

  doc.save(`barcodes_${new Date().toISOString().slice(0, 10)}.pdf`);
};

import React, { useEffect, useRef } from 'react';
import JsBarcode from 'jsbarcode';
import { Product } from '../types';

interface BarcodeLabelProps {
  product: Product;
}

export const BarcodeLabel: React.FC<BarcodeLabelProps> = ({ product }) => {
  const canvasRef = useRef<HTMLCanvasElement>(null);

  useEffect(() => {
    if (canvasRef.current) {
      try {
        JsBarcode(canvasRef.current, product.sku, {
          format: 'CODE128',
          displayValue: false,
          height: 40,
          width: 2,
          margin: 0,
          background: 'transparent'
        });
      } catch (e) {
        console.error("Invalid SKU for barcode generation");
      }
    }
  }, [product.sku]);

  return (
    <div className="w-[280px] h-[140px] bg-white border border-gray-200 shadow-sm rounded-md p-3 flex flex-col items-center justify-center relative overflow-hidden group hover:border-indigo-300 transition-colors">
      {/* Price Tag (Corner) */}
      <div className="absolute top-2 right-3 text-xs font-bold text-gray-500">
        {product.price.startsWith('$') ? product.price : `$${product.price}`}
      </div>

      {/* Article Name */}
      <div className="text-center w-full px-2 mb-1">
        <h3 className="font-bold text-gray-900 text-sm uppercase leading-tight line-clamp-2">
          {product.articleName}
        </h3>
      </div>

      {/* Size and Color */}
      <div className="text-xs text-gray-600 mb-2 font-medium">
        {product.size} <span className="mx-1 text-gray-400">•</span> {product.color}
      </div>

      {/* Barcode */}
      <div className="w-full flex justify-center mb-1">
        <canvas ref={canvasRef} className="h-10 w-auto max-w-full" />
      </div>

      {/* SKU */}
      <div className="text-sm font-mono font-bold text-gray-800 tracking-wider">
        {product.sku}
      </div>
    </div>
  );
};

import React, { useState } from 'react';
import { Product } from '../types';
import { Plus, Trash2 } from 'lucide-react';

interface InputFormProps {
  onAdd: (product: Product) => void;
}

export const InputForm: React.FC<InputFormProps> = ({ onAdd }) => {
  const [formData, setFormData] = useState({
    articleName: '',
    sku: '',
    price: '',
    size: '',
    color: ''
  });

  const handleChange = (e: React.ChangeEvent<HTMLInputElement>) => {
    setFormData({ ...formData, [e.target.name]: e.target.value });
  };

  const handleSubmit = (e: React.FormEvent) => {
    e.preventDefault();
    if (!formData.articleName || !formData.sku) return;

    onAdd({
      id: crypto.randomUUID(),
      ...formData
    });

    setFormData({
      articleName: '',
      sku: '',
      price: '',
      size: '',
      color: ''
    });
  };

  return (
    <form onSubmit={handleSubmit} className="bg-white p-6 rounded-xl shadow-sm border border-slate-100">
      <div className="grid grid-cols-1 md:grid-cols-2 gap-4">
        <div className="md:col-span-2">
          <label className="block text-sm font-medium text-slate-700 mb-1">Article Name</label>
          <input
            name="articleName"
            value={formData.articleName}
            onChange={handleChange}
            placeholder="e.g. Johnny Collar Cable Knit Polo"
            className="w-full px-3 py-2 border border-slate-300 rounded-lg focus:ring-2 focus:ring-indigo-500 focus:border-indigo-500 outline-none transition-all"
            required
          />
        </div>

        <div>
          <label className="block text-sm font-medium text-slate-700 mb-1">SKU</label>
          <input
            name="sku"
            value={formData.sku}
            onChange={handleChange}
            placeholder="e.g. SM519T0028"
            className="w-full px-3 py-2 border border-slate-300 rounded-lg focus:ring-2 focus:ring-indigo-500 focus:border-indigo-500 outline-none transition-all"
            required
          />
        </div>

        <div>
          <label className="block text-sm font-medium text-slate-700 mb-1">Price</label>
          <input
            name="price"
            type="number"
            step="0.01"
            value={formData.price}
            onChange={handleChange}
            placeholder="29.99"
            className="w-full px-3 py-2 border border-slate-300 rounded-lg focus:ring-2 focus:ring-indigo-500 focus:border-indigo-500 outline-none transition-all"
          />
        </div>

        <div>
          <label className="block text-sm font-medium text-slate-700 mb-1">Size</label>
          <input
            name="size"
            value={formData.size}
            onChange={handleChange}
            placeholder="e.g. XL"
            className="w-full px-3 py-2 border border-slate-300 rounded-lg focus:ring-2 focus:ring-indigo-500 focus:border-indigo-500 outline-none transition-all"
          />
        </div>

        <div>
          <label className="block text-sm font-medium text-slate-700 mb-1">Color</label>
          <input
            name="color"
            value={formData.color}
            onChange={handleChange}
            placeholder="e.g. Echo Gray"
            className="w-full px-3 py-2 border border-slate-300 rounded-lg focus:ring-2 focus:ring-indigo-500 focus:border-indigo-500 outline-none transition-all"
          />
        </div>
      </div>

      <div className="mt-6 flex justify-end">
        <button
          type="submit"
          className="flex items-center gap-2 bg-indigo-600 hover:bg-indigo-700 text-white px-5 py-2.5 rounded-lg font-medium transition-colors shadow-sm"
        >
          <Plus size={18} />
          Add to Queue
        </button>
      </div>
    </form>
  );
