import React, { useRef, useState } from 'react';
import Papa from 'papaparse';
import { Upload, FileText, AlertCircle, CheckCircle2 } from 'lucide-react';
import { Product } from '../types';

interface BulkUploadProps {
  onUpload: (products: Product[]) => void;
}

export const BulkUpload: React.FC<BulkUploadProps> = ({ onUpload }) => {
  const fileInputRef = useRef<HTMLInputElement>(null);
  const [error, setError] = useState<string | null>(null);
  const [successMsg, setSuccessMsg] = useState<string | null>(null);

  const handleFileUpload = (e: React.ChangeEvent<HTMLInputElement>) => {
    const file = e.target.files?.[0];
    if (!file) return;

    setError(null);
    setSuccessMsg(null);

    if (file.type !== 'text/csv' && !file.name.endsWith('.csv')) {
      setError('Please upload a valid CSV file.');
      return;
    }

    Papa.parse(file, {
      header: true,
      skipEmptyLines: true,
      transformHeader: (header) => header.toLowerCase().trim(),
      complete: (results) => {
        if (results.errors.length > 0) {
          console.error("CSV Errors:", results.errors);
          setError('Error parsing CSV. Please check the format.');
          return;
        }

        const parsedProducts: Product[] = results.data.map((row: any) => {
          // Robust mapping for varying header names
          return {
            id: crypto.randomUUID(),
            articleName: row['article name'] || row['name'] || row['article'] || 'Unknown Item',
            sku: row['sku'] || row['id'] || '0000',
            price: row['price'] || row['cost'] || '0',
            size: row['size'] || '-',
            color: row['color'] || row['colour'] || '-',
          };
        }).filter(p => p.sku !== '0000'); // Filter out empty rows if any

        if (parsedProducts.length === 0) {
            setError("No valid products found. Ensure headers are: Article Name, SKU, Price, Size, Color.");
        } else {
            onUpload(parsedProducts);
            setSuccessMsg(`Successfully processed ${parsedProducts.length} items.`);
        }
      },
      error: (err) => {
        setError(`Failed to read file: ${err.message}`);
      }
    });

    // Reset input
    if (fileInputRef.current) fileInputRef.current.value = '';
  };

  return (
    <div className="bg-white p-8 rounded-xl shadow-sm border border-slate-100 flex flex-col items-center justify-center text-center">
      <div 
        onClick={() => fileInputRef.current?.click()}
        className="w-full max-w-md border-2 border-dashed border-slate-300 rounded-xl p-10 hover:border-indigo-500 hover:bg-slate-50 transition-all cursor-pointer group"
      >
        <div className="w-16 h-16 bg-indigo-50 rounded-full flex items-center justify-center mx-auto mb-4 group-hover:scale-110 transition-transform">
          <Upload className="text-indigo-600" size={32} />
        </div>
        <h3 className="text-lg font-semibold text-slate-800 mb-2">Click to upload CSV</h3>
        <p className="text-sm text-slate-500 mb-6">
          Headers required: Article Name, SKU, Price, Size, Color
        </p>
        <button className="bg-white border border-slate-300 text-slate-700 px-4 py-2 rounded-lg text-sm font-medium group-hover:border-indigo-500 group-hover:text-indigo-600 transition-colors">
          Select File
        </button>
      </div>

      <input 
        type="file" 
        ref={fileInputRef} 
        onChange={handleFileUpload} 
        accept=".csv" 
        className="hidden" 
      />

      <div className="mt-6 w-full max-w-md bg-slate-50 p-4 rounded-lg text-left">
        <h4 className="text-xs font-semibold text-slate-500 uppercase tracking-wider mb-2">Example CSV Format</h4>
        <div className="font-mono text-xs text-slate-600 bg-white border border-slate-200 p-3 rounded">
          Article Name, SKU, Price, Size, Color<br/>
          Cotton Tee, CT100-BLK, 19.99, M, Black<br/>
          Denim Jeans, DJ500-BLU, 49.99, 32, Dark Wash
        </div>
      </div>

      {error && (
        <div className="mt-4 flex items-center gap-2 text-red-600 bg-red-50 px-4 py-2 rounded-lg text-sm">
            <AlertCircle size={16} />
            {error}
        </div>
      )}

      {successMsg && (
        <div className="mt-4 flex items-center gap-2 text-green-600 bg-green-50 px-4 py-2 rounded-lg text-sm">
            <CheckCircle2 size={16} />
            {successMsg}
        </div>
      )}
    </div>
  );
};

import React, { useState } from 'react';
import { Product, InputMode } from './types';
import { InputForm } from './components/InputForm';
import { BulkUpload } from './components/BulkUpload';
import { BarcodeLabel } from './components/BarcodeLabel';
import { generatePDF } from './services/pdfGenerator';
import { 
  Layout, 
  FileSpreadsheet, 
  PenLine, 
  Download, 
  Trash2, 
  Printer, 
  Package
} from 'lucide-react';

export default function App() {
  const [products, setProducts] = useState<Product[]>([]);
  const [mode, setMode] = useState<InputMode>('single');

  const addProduct = (product: Product) => {
    setProducts((prev) => [product, ...prev]);
  };

  const addBulkProducts = (newProducts: Product[]) => {
    setProducts((prev) => [...newProducts, ...prev]);
  };

  const removeProduct = (id: string) => {
    setProducts((prev) => prev.filter((p) => p.id !== id));
  };

  const clearAll = () => {
    if (confirm('Are you sure you want to clear all items?')) {
      setProducts([]);
    }
  };

  const handleDownloadPDF = () => {
    if (products.length === 0) return;
    generatePDF(products);
  };

  return (
    <div className="min-h-screen bg-slate-50/50 flex flex-col font-sans">
      {/* Navbar */}
      <header className="bg-white border-b border-slate-200 sticky top-0 z-10">
        <div className="max-w-7xl mx-auto px-4 sm:px-6 lg:px-8 h-16 flex items-center justify-between">
          <div className="flex items-center gap-3">
            <div className="bg-indigo-600 p-2 rounded-lg text-white">
              <Printer size={20} />
            </div>
            <div>
              <h1 className="text-lg font-bold text-slate-900 tracking-tight">Barcodify Pro</h1>
              <p className="text-xs text-slate-500 font-medium">Retail Label Generator</p>
            </div>
          </div>

          <div className="flex items-center gap-2">
            <span className="text-sm text-slate-500 mr-2 hidden sm:inline">
              {products.length} {products.length === 1 ? 'Label' : 'Labels'} ready
            </span>
            <button
              onClick={handleDownloadPDF}
              disabled={products.length === 0}
              className={`flex items-center gap-2 px-4 py-2 rounded-lg font-medium transition-all ${
                products.length > 0 
                  ? 'bg-indigo-600 text-white hover:bg-indigo-700 shadow-md hover:shadow-lg' 
                  : 'bg-slate-200 text-slate-400 cursor-not-allowed'
              }`}
            >
              <Download size={18} />
              <span className="hidden sm:inline">Export PDF</span>
            </button>
          </div>
        </div>
      </header>

      <main className="flex-1 max-w-7xl w-full mx-auto px-4 sm:px-6 lg:px-8 py-8">
        <div className="grid grid-cols-1 lg:grid-cols-12 gap-8 h-full">

          {/* Left Column: Input Section */}
          <div className="lg:col-span-5 flex flex-col gap-6">

            {/* Mode Switcher */}
            <div className="bg-slate-200/50 p-1 rounded-xl flex">
              <button
                onClick={() => setMode('single')}
                className={`flex-1 flex items-center justify-center gap-2 py-2.5 text-sm font-medium rounded-lg transition-all ${
                  mode === 'single' 
                    ? 'bg-white text-indigo-600 shadow-sm ring-1 ring-slate-200' 
                    : 'text-slate-600 hover:text-slate-900'
                }`}
              >
                <PenLine size={16} />
                Single Entry
              </button>
              <button
                onClick={() => setMode('bulk')}
                className={`flex-1 flex items-center justify-center gap-2 py-2.5 text-sm font-medium rounded-lg transition-all ${
                  mode === 'bulk' 
                    ? 'bg-white text-indigo-600 shadow-sm ring-1 ring-slate-200' 
                    : 'text-slate-600 hover:text-slate-900'
                }`}
              >
                <FileSpreadsheet size={16} />
                Bulk CSV Upload
              </button>
            </div>

            {/* Form Area */}
            <div className="transition-all duration-300 ease-in-out">
              {mode === 'single' ? (
                <div className="space-y-4">
                  <div className="flex items-center justify-between">
                    <h2 className="text-lg font-semibold text-slate-800">Add Product</h2>
                  </div>
                  <InputForm onAdd={addProduct} />
                </div>
              ) : (
                <div className="space-y-4">
                  <h2 className="text-lg font-semibold text-slate-800">Upload Data</h2>
                  <BulkUpload onUpload={addBulkProducts} />
                </div>
              )}
            </div>

            {/* Instructions / Info */}
            <div className="bg-indigo-50 p-6 rounded-xl border border-indigo-100">
              <h3 className="text-indigo-900 font-semibold mb-2 flex items-center gap-2">
                <Layout size={18} />
                Output Layout
              </h3>
              <p className="text-sm text-indigo-700/80 leading-relaxed">
                The generated PDF will follow a standard 3x8 grid layout (24 labels per A4 page).
                Compatible with standard sticky label sheets. Each label includes the item name, variant details, SKU barcode (Code 128), and price.
              </p>
            </div>
          </div>

          {/* Right Column: Preview Section */}
          <div className="lg:col-span-7 flex flex-col h-full min-h-[500px]">
            <div className="flex items-center justify-between mb-4">
              <h2 className="text-lg font-semibold text-slate-800 flex items-center gap-2">
                <Package size={20} className="text-indigo-500" />
                Print Queue
              </h2>
              {products.length > 0 && (
                <button 
                  onClick={clearAll}
                  className="text-red-500 hover:text-red-600 text-sm font-medium flex items-center gap-1 hover:bg-red-50 px-3 py-1.5 rounded-lg transition-colors"
                >
                  <Trash2 size={16} />
                  Clear Queue
                </button>
              )}
            </div>

            {/* List Container */}
            <div className="bg-white rounded-xl shadow-sm border border-slate-200 flex-1 overflow-hidden flex flex-col">
              {products.length === 0 ? (
                <div className="flex-1 flex flex-col items-center justify-center text-slate-400 p-12">
                  <div className="w-16 h-16 bg-slate-50 rounded-full flex items-center justify-center mb-4">
                    <Layout size={32} className="opacity-50" />
                  </div>
                  <p className="text-lg font-medium text-slate-500">Queue is empty</p>
                  <p className="text-sm max-w-xs text-center mt-2">Add products manually or upload a CSV file to generate your barcodes.</p>
                </div>
              ) : (
                <div className="overflow-y-auto p-6 h-0 flex-1 bg-slate-50/50">
                  <div className="grid grid-cols-1 xl:grid-cols-2 gap-4">
                    {products.map((product) => (
                      <div key={product.id} className="relative group">
                        <BarcodeLabel product={product} />
                        <button
                          onClick={() => removeProduct(product.id)}
                          className="absolute -top-2 -right-2 bg-white text-red-500 border border-red-100 p-1.5 rounded-full shadow-sm opacity-0 group-hover:opacity-100 transition-all hover:bg-red-50 hover:scale-110"
                          title="Remove item"
                        >
                          <Trash2 size={14} />
                        </button>
                      </div>
                    ))}
                  </div>
                </div>
              )}

              {/* Footer Stat */}
              <div className="p-4 border-t border-slate-100 bg-white text-xs text-slate-500 flex justify-between items-center">
                <span>Total Items: {products.length}</span>
                <span>Format: Code 128</span>
              </div>
            </div>
          </div>

        </div>
      </main>
    </div>
  );
}

import jsPDF from 'jspdf';
import JsBarcode from 'jsbarcode';
import { Product } from '../types';

// Helper to generate a base64 barcode image
const generateBarcodeBase64 = (sku: string): string => {
  const canvas = document.createElement('canvas');
  JsBarcode(canvas, sku, {
    format: 'CODE128',
    displayValue: false, // We will draw the text manually in the PDF for better control
    margin: 0,
    height: 40,
    width: 2,
    fontSize: 0,
  });
  return canvas.toDataURL('image/jpeg');
};

export const generatePDF = (products: Product[]) => {
  // A4 dimensions in mm: 210 x 297
  const doc = new jsPDF({
    orientation: 'p',
    unit: 'mm',
    format: 'a4',
  });

  const pageWidth = 210;
  // pageHeight is 297 but not used explicitly in logic below

  // Label Configuration (approx 3 x 8 grid)
  const cols = 3;
  const rows = 8;
  const labelWidth = 64; 
  const labelHeight = 34;
  const marginX = (pageWidth - (cols * labelWidth)) / 2;
  const marginY = 12;
  const gutterX = 2; // Spacing between cols
  const gutterY = 4; // Spacing between rows

  let colIndex = 0;
  let rowIndex = 0;

  products.forEach((product, index) => {
    // Check if new page is needed
    if (index > 0 && index % (cols * rows) === 0) {
      doc.addPage();
      colIndex = 0;
      rowIndex = 0;
    }

    const x = marginX + colIndex * (labelWidth + gutterX);
    const y = marginY + rowIndex * (labelHeight + gutterY);

    // --- Draw Label Border (Optional, helpful for cutting if not using pre-cut paper) ---
    doc.setDrawColor(200, 200, 200);
    doc.setLineWidth(0.1);
    doc.rect(x, y, labelWidth, labelHeight);

    // --- Content ---
    const centerX = x + (labelWidth / 2);

    // 1. Article Name (Top)
    doc.setFont("helvetica", "bold");
    doc.setFontSize(9);
    doc.setTextColor(0, 0, 0);

    // Truncate text if too long
    const name = product.articleName.toUpperCase();
    const splitName = doc.splitTextToSize(name, labelWidth - 4);

    // If name is too long, just take first 2 lines
    const linesToPrint = splitName.length > 2 ? splitName.slice(0, 2) : splitName;
    doc.text(linesToPrint, centerX, y + 5, { align: "center" });

    let currentY = y + 5 + (linesToPrint.length * 4); // Adjust Y based on lines

    // 2. Size & Color & Price (Middle) - Combined Line
    doc.setFont("helvetica", "normal");
    doc.setFontSize(8);

    // Clean price string to ensure it's just numbers/decimals
    const priceVal = product.price ? product.price.toString().replace(/[^0-9.]/g, '') : '0';
    const metaText = `${product.size} • ${product.color} • PKR ${priceVal}`;

    doc.text(metaText, centerX, currentY, { align: "center" });

    currentY += 2; // Spacer

    // 3. Barcode (Center)
    try {
      const barcodeData = generateBarcodeBase64(product.sku);
      const barcodeWidth = 40;
      const barcodeHeight = 10;
      doc.addImage(barcodeData, 'JPEG', centerX - (barcodeWidth / 2), currentY, barcodeWidth, barcodeHeight);

      currentY += barcodeHeight + 4; // Move below barcode
    } catch (e) {
      console.error("Error generating barcode for", product.sku, e);
    }

    // 4. SKU (Bottom)
    doc.setFont("courier", "bold"); // Monospace looks nice for SKU
    doc.setFontSize(10);
    doc.text(product.sku, centerX, currentY, { align: "center" });

    // Increment Grid Position
    colIndex++;
    if (colIndex >= cols) {
      colIndex = 0;
      rowIndex++;
    }
  });

  doc.save(`barcodes_${new Date().toISOString().slice(0, 10)}.pdf`);
};

import React, { useEffect, useRef } from 'react';
import JsBarcode from 'jsbarcode';
